SELECT 'gongkao', '调查统计型容斥', 'kp-xingce-quantity-math-operation-inclusion-exclusion-survey', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "调查统计型容斥"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "给出一堆属性的人数，求总人数或某个子集人数。核心是：不要重复计算！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“某班有 50 人，喜欢篮球的有 30 人，喜欢足球的有 25 人，两样都喜欢的有 10 人……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把喜欢篮球的人和喜欢足球的人加起来（30+25=55）。但这 55 人里，那 10 个“两样都喜欢”的人被数了两次！必须把多算的一次减掉。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{总人数} = \\text{至少喜欢一项的人} + \\text{都不喜欢的人}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出已知集合的总人数 (如 A, B, 都不)] --> B{题目有几个集合?}\nB -- 2个集合 --> C[套用两集合容斥公式]\nB -- 3个集合 --> D[套用三集合容斥公式或画图法]\nC --> E[把所有元素丢进公式, 解出唯一的未知数]\nD --> E"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 班级 50 人，喜欢篮球 30 人，喜欢足球 25 人，两样都不喜欢的 5 人。求两样都喜欢的有几人？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "至少喜欢一项的人数：总人数(50) - 都不喜欢(5) = 45 人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如果不考虑重复，总和：篮球(30) + 足球(25) = 55 人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "多出来的人数：55 - 45 = 10 人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结论：多出来的这 10 个人，就是被重复计算的“两样都喜欢”的人！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记加上“都不”的人：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多同学一上来就 50 = 30 + 25 - x。错！50是全集，30+25-x 只是“至少喜欢一项”的并集。必须是 50 = 30 + 25 - x + 5（都不喜欢的人）。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "永远在等式左边写上【总人数】，等式右边最后加上【都不喜欢的人】。这是容斥原理的不破金身。"}]}]}$$ AS jsonb), NULL, '调查统计型容斥的核心考点与实战推导。', category_node.id, CAST('["数量关系", "容斥问题", "调查统计型容斥"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_inclusion_exclusion_survey", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
